from lib import *
S = SS('t28')
steps = [
    step("没有幂等处理的 POST /orders:客户端超时设 100 ms、最多尝试 3 次;30% 的请求服务端这次处理要 250 ms,客户端必然先超时。200 个逻辑请求:132 个正常请求一次拿到 201;68 个慢请求三次尝试全部超时,客户端最后没拿到任何响应。可是库里一共有 336 个订单,多出 136 个重复订单——每个慢请求的三次尝试,服务端都各自处理完并建了一个订单,客户端一个都没等到。", t=tl(S(1)), mark=lidx(S(1), '库里的订单数 336', '多出 136'), done=lidx(S(1), 'timeout→timeout→timeout'), b=bars([['逻辑请求', 200, '200'], ['库里的订单数', 336, '336'], ['多出的重复订单', 136, '136']], 340, cur=[0], mark=[1, 2]), kv=KV([['慢请求', '3 次尝试都超时,没拿到响应'], ['服务端', '三次都处理完了,建了 3 个订单'], ['重复订单', '136 个']], ['重复订单'])),
    step("同样的负载,改用 POST /v2/orders + Idempotency-Key(每个逻辑请求一个 key,重试用同一个 key,遇到 409 等 0.2 秒再试)。200 个逻辑请求:客户端全部拿到订单号,库里的订单数正好 200,多出 0 个;idem 表 200 行,全部 DONE。132 个正常请求一次 201;68 个慢请求的序列是 timeout → 409 → 201(重放):第一次超时(服务端还在处理),第二次遇到 PROCESSING 返回 409,等 0.2 s 后第三次拿到保存的响应(带 Idempotent-Replayed: true)。服务端从头到尾只执行了一次。", t=tl(S(2)), mark=lidx(S(2), 'timeout→409→201'), done=lidx(S(2), '库里的订单数 200'), b=bars([['逻辑请求', 200, '200'], ['库里的订单数', 200, '200'], ['多出的重复订单', 0, '0'], ['走“超时 → 409 → 重放”的请求', 68, '68']], 200, done=[0, 1, 2], cur=[3]), kv=KV([['有 Idempotency-Key', '库里 200 个订单,0 个重复'], ['慢请求', '超时 → 409(处理中)→ 重放原响应'], ['idem 表', '200 行,全部 DONE']], ['有 Idempotency-Key'])),
    step("两个相同的请求同时到达(同一个 key):100 对,每一对的结果都是“201 + 409”——只有一个抢到 PROCESSING 占位去执行,另一个拿到 409(这个请求正在处理中);库里订单数正好 100。占位这一步靠 key 的唯一性保证只有一个请求能成功,不是靠先查后写。", t=tl(S(3)), mark=lidx(S(3), '结果组合'), b=bars([['201 + 409 的对数', 100, '100 / 100'], ['库里订单数', 100, '100']], 100, done=[0, 1]), kv=KV([['同时到达', '一个 201,一个 409'], ['订单数', '100 对 → 100 个订单'], ['原因', 'key 唯一性保证占位只有一个成功']], ['原因'])),
    step("同一个 key、不同的请求内容:第 1 次(amount=100)返回 201、订单 637;第 2 次同样的内容返回同样的 201 {order_id: 637},带 Idempotent-Replayed: true;第 3 次同一个 key 但 amount=999,返回 422:同一个 Idempotency-Key 对应了不同的请求内容,而不是把第 1 次的响应原样还给它;库里只有 1 个订单。服务端用请求体的指纹(SHA-256)和保存的比对,发现 key 被拿去做别的事。", t=tl(S(4)), mark=lidx(S(4), '第 3 次'), done=lidx(S(4), '第 1 次'), b=bars([['第 2 次(同内容)重放的订单号', 637, '637(同第 1 次)'], ['第 3 次(不同内容)的响应码', 422, '422'], ['库里订单数', 1, '1']], 640, done=[0, 2], mark=[1]), kv=KV([['同 key 同内容', '重放原响应'], ['同 key 不同内容', '422,拒绝'], ['依据', '请求体的指纹']], ['依据'])),
    step("幂等键有有效期。把 key 记录的 TTL 设成 0.5 秒:第 1 次返回 201、订单 638;客户端 1 秒后(比如离线重发)用同一个 key 重试,服务端已经不认识这个 key,当作新请求,返回 201、订单 639,没有 Idempotent-Replayed 头;库里订单数 2——同一个请求被执行了两次。key 的保留期必须比客户端可能重试的最长窗口(包括离线队列、人工重发)长。", t=tl(S(5)), mark=lidx(S(5), '1 秒后用同一个 key 重试'), b=bars([['第 1 次的订单号', 638, '638'], ['TTL 过期后重试的订单号', 639, '639'], ['库里订单数', 2, '2(应为 1)']], 640, cur=[0], mark=[1, 2]), kv=KV([['TTL 内', '重放原响应'], ['TTL 外', '当作新请求,再执行一次'], ['要求', '保留期 > 最长重试窗口']], ['要求'])),
    step("不用幂等键,让客户端自己选订单号:PUT /orders/<外部订单号>,服务端用 INSERT ... ON DUPLICATE KEY UPDATE。同样 200 个逻辑请求、同样的超时重试:库里的订单数 200,多出 0 个;idem 表 0 行。68 个慢请求客户端同样三次都超时、没拿到响应,但服务端每次都覆盖同一行,没有重复。PUT 本身是幂等的,不需要额外的 key 表;前提是客户端能提前生成稳定的订单号,而且“两次 PUT 之间别人改过”的情形要靠版本 / 条件请求(If-Match)另外处理。", t=tl(S(6)), mark=lidx(S(6), '库里的订单数 200'), done=lidx(S(6), '客户端'), b=bars([['PUT:库里订单数', 200, '200'], ['PUT:idem 表行数', 0, '0'], ['POST + key:idem 表行数', 200, '200']], 200, done=[0, 1], cur=[2]), kv=KV([['PUT + 外部订单号', '0 重复,不需要 key 表'], ['POST + Idempotency-Key', '0 重复,要 idem 表'], ['前提', '客户端能生成稳定的订单号']], ['前提'])),
]
A = mkartt('t28', 28, '分布式事务,幂等,Idempotency-Key,HTTP,重试,MySQL,真实验证,动画演示',
    '实测幂等接口的设计:无幂等的 POST 在 100 ms 超时重试下 200 个请求建了 336 个订单(多 136 个);带 Idempotency-Key 后 0 个重复,慢请求走“超时 → 409 → 重放”;同时到达的 100 对只执行 100 次;同 key 不同内容返回 422;key 过期后会再执行一次;PUT + 外部订单号同样 0 重复且不需要 key 表。',
    '客户端超时了就重试,这是网络世界的常态。怎么设计 HTTP 接口,让同一个请求重复提交不会重复执行?Idempotency-Key 怎么用、同时到达怎么办、key 被拿去干别的怎么办、key 能保留多久、有没有不用 key 的办法?这篇用真实的 HTTP 服务和 MySQL 逐个验证。',
    [('136 个', '没有幂等处理时,200 个请求因超时重试在库里多出的重复订单数(用 Idempotency-Key 后是 0)'), ('201 + 409 × 100', '100 对同时到达的相同请求的结果:只有一个执行,另一个得到“处理中”'), ('422', '同一个 Idempotency-Key 带不同内容时的响应:拒绝,不把旧响应还给新请求')],
    [('没有幂等处理', '<p>超时的请求其实已经在服务端处理,客户端不知道,重试又建一个,慢请求每次尝试都产生一个订单。</p>'),
     ('Idempotency-Key', '<p>每个逻辑请求一个 key,重试沿用;服务端先占位,处理中返回 409,处理完保存响应,之后重放。</p>'),
     ('并发占位', '<p>同一个 key 同时到达,靠唯一键只让一个请求执行,另一个得到 409。</p>'),
     ('请求指纹', '<p>同一个 key 对应不同内容要拒绝(422),不能把旧响应还给新请求。</p>'),
     ('保留期', '<p>key 记录要保留得比客户端最长的重试窗口久,否则过期后重试会再执行一次。</p>'),
     ('PUT 与外部订单号', '<p>客户端选稳定的资源 id,用 PUT 覆盖同一行,天然幂等,不需要 key 表。</p>')],
    steps,
    [ENV_T + '。本篇用 Python http.server(线程化)写的小服务和 MySQL 26.7.0(orders、idem 两张表),客户端用 http.client,超时 100 ms、最多 3 次;“慢请求”由请求头 X-Slow-Ms 让服务端故意多处理 250 ms;幂等键的占位 / 响应保存 / 指纹比对是我自己写的实现(约几十行),不是某个框架;第五节把 TTL 设成 0.5 秒,第三节两个并发请求用线程 + 屏障',
     '没有验证:反向代理 / 网关层的重试(比如 Nginx 对上游的自动重试);HTTP/2 与连接复用对超时行为的影响;对外的支付网关(Stripe 之类)的 Idempotency-Key 具体语义;在分布式部署(多个服务实例、读写分离)下 idem 表的一致性;响应体很大时保存响应的成本;服务端 stderr 里有若干 ConnectionResetError(客户端超时后关闭连接引起的),不影响结果'],
    '幂等接口')
